// PROPOSAL ONLY: select the original painted emoji span; do not substitute
// DOM text as terminal data or alter its font/text/style. Id is probe metadata.
const glyphStyle = await page.evaluate(() => {
  const row = document.querySelector('.xterm-rows')?.children[2];
  const span = [...(row?.querySelectorAll('span') ?? [])]
    .find(node => node.textContent?.includes('🙂'));
  if (!span) throw Error('Original glyph span unavailable');
  span.id = 'diagnostic-emoji-font-probe';
  const css = getComputedStyle(span);
  return { text: span.textContent, font: css.font, family: css.fontFamily,
    size: css.fontSize, weight: css.fontWeight, style: css.fontStyle,
    letterSpacing: css.letterSpacing, box: span.getBoundingClientRect().toJSON() };
});
const cdp = await context.newCDPSession(page);
await cdp.send('DOM.enable');
await cdp.send('CSS.enable');
const { root } = await cdp.send('DOM.getDocument', { depth: 0 });
const { nodeId } = await cdp.send('DOM.querySelector', {
  nodeId: root.nodeId, selector: '#diagnostic-emoji-font-probe'
});
const { fonts } = await cdp.send('CSS.getPlatformFontsForNode', { nodeId });
